// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Phishable c;

    function setUp() public {
        c = new Phishable(address(this));
    }

    function _run(address sender) internal {
        bool reverted;
        vm.assume(sender == address(this) || sender != address(this));
        try c.withdrawAll(sender) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted == (address(this) != c.owner()));
    }

    function testFuzz_run(address sender) public {
        vm.assume(uint160(sender) > 255 && sender != address(this) && sender != address(c) && sender != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && sender != 0x000000000000000000636F6e736F6c652e6c6f67 && sender != 0x4e59b44847b379578588920cA78FbF26c0B4956C && sender != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(sender);
    }

    receive() external payable { }
}
